(()=>{"use strict";const ready=()=>{const shell=document.getElementById("siteShellHeader"),menu=shell&&shell.querySelector(".shell-menu"),links=document.getElementById("siteShellLinks");if(menu&&links&&!menu.dataset.coreBound){menu.dataset.coreBound="1";const close=()=>{links.classList.remove("is-open");menu.classList.remove("is-open");menu.setAttribute("aria-expanded","false")};menu.addEventListener("click",()=>{const open=links.classList.toggle("is-open");menu.classList.toggle("is-open",open);menu.setAttribute("aria-expanded",String(open))});links.addEventListener("click",e=>{if(e.target.closest("a"))close()});addEventListener("resize",()=>{if(innerWidth>820)close()},{passive:true})}const legacy=document.querySelector(".menu-toggle"),nav=document.querySelector(".nav");if(legacy&&nav&&!legacy.dataset.coreBound){legacy.dataset.coreBound="1";legacy.addEventListener("click",()=>{const open=nav.classList.toggle("active");legacy.classList.toggle("active",open);legacy.setAttribute("aria-expanded",String(open))})}document.querySelectorAll(".faq-question").forEach(button=>{if(button.closest(".blog-faq,.article-faq")||button.dataset.coreBound)return;button.dataset.coreBound="1";button.addEventListener("click",()=>{const item=button.closest(".faq-item"),open=!item.classList.contains("active");item.classList.toggle("active",open);button.setAttribute("aria-expanded",String(open));const icon=button.querySelector(".faq-icon,.ui-icon.fa-plus,.ui-icon.fa-minus");if(icon)icon.textContent=open?"−":"+"})});document.querySelectorAll("#current-year").forEach(el=>el.textContent=String(new Date().getFullYear()));const top=document.getElementById("scrollTop")||document.querySelector(".scroll-top");if(top&&!top.dataset.coreBound){top.dataset.coreBound="1";const update=()=>top.classList.toggle("show",scrollY>320);addEventListener("scroll",update,{passive:true});update();top.addEventListener("click",()=>scrollTo({top:0,behavior:"smooth"}))}const frames=[...document.querySelectorAll("iframe[data-src]")];const load=frame=>{if(frame.dataset.src&&!frame.getAttribute("src")){frame.src=frame.dataset.src;frame.removeAttribute("data-src")}};if("IntersectionObserver"in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){load(entry.target);observer.unobserve(entry.target)}}),{rootMargin:"300px"});frames.forEach(frame=>observer.observe(frame))}else frames.forEach(load)};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",ready,{once:true}):ready()})();